import { put, get } from '@vercel/blob';

const P={"191":["Ostatni król z dynastii Piastów","Ostatni król z dynastii Piastów\nGdy Kazimierz Wielki rozpoczynał rządy, Polska nie liczyła się za granicą. Dzięki królowi stała się ważnym państwem Europy Środkowej. Monarcha pośredniczył w międzynarodowych sporach, np. Czech z Węgrami. W 1364 r. zorganizował zjazd monarchów w Krakowie, gdzie gościł cesarza, dwóch królów i licznych książąt. To wtedy odbyła się słynna uczta u Wierzynka. Taki zjazd byłby nie do pomyślenia w początkach rządów Kazimierza.\nKról Kazimierz Wielki zmarł w 1370 r. Jego śmierć była dla mieszkańców Polski podwójnym ciosem. Po pierwsze, stracili wybitnego władcę. Po drugie, król nie miał dzieci, które mogłyby odziedziczyć po nim tron. Był ostatnim monarchą z dynastii Piastów, rządzącej Polską przez ponad 400 lat.\nNagrobek Kazimierza Wielkiego w katedrze wawelskiej. Został wykonany po 1370 r., a ufundował go, tzn. zamówił i zapłacił za niego, następca zmarłego króla – Ludwik Węgierski. Postać Kazimierza wyrzeźbiono z marmuru; król leży z głową na poduszce, ubrany w strój koronacyjny.\n13. Co świadczyło o wzroście znaczenia Polski za rządów Kazimierza Wielkiego?\nPytania i polecenia. A. Wyjaśnij, w jaki sposób Kazimierz Wielki wzmocnił państwo. B. Dlaczego, twoim zdaniem, Kazimierza nazwano Wielkim?\nTo, co najważniejsze. Kazimierz Wielki – syn Władysława Łokietka, król Polski w latach 1333–1370; ostatni monarcha z dynastii Piastów.\nStosunki z Krzyżakami: 1. Proces w Warszawie (1339) – mimo wyroku Krzyżacy nie oddali Polsce Pomorza Gdańskiego. 2. Pokój wieczysty w Kaliszu (1343): zakon zwrócił Polsce Kujawy i ziemię dobrzyńską, a Pomorze Gdańskie było „wieczystą jałmużną” króla dla zakonu.\nRuś Halicka, podbój w latach 1340–1366: król przyłączył większość Rusi Halickiej do Polski i wprowadził tolerancję religijną dla prawosławnych Rusinów.\nWzmocnienie państwa: jedna moneta; lokacja ok. 100 miast i ponad 1000 wsi; budowa zamków i murów miejskich.\nPrawo: spisane statuty praw dla Wielkopolski i Małopolski zamiast prawa ustnego.\nNauka: założenie uniwersytetu – Akademii Krakowskiej (1364).\nWzrost znaczenia Polski: zjazd monarchów w Krakowie (1364)."],"192":["VIII. Polska i Litwa","VIII. Polska i Litwa\n35. Unia Polski z Litwą.\n36. Wielka wojna z zakonem krzyżackim.\n37. Synowie Jagiełły.\n38. Od rycerstwa do szlachty.\n39. Polska i Litwa w XV wieku.\nBitwa pod Grunwaldem. Fragment obrazu Wojciecha Kossaka z 1931 r."],"193":["Unia Polski z Litwą – unia polsko-węgierska","35. Unia Polski z Litwą\nOś czasu: 1370 – śmierć Kazimierza Wielkiego, koronacja Ludwika Węgierskiego na króla Polski; 1382 – śmierć Ludwika Węgierskiego; 1384 – koronacja Jadwigi na króla Polski; 1385 – umowa w Krewie; 1386 – unia polsko-litewska, koronacja Władysława Jagiełły na króla Polski; 1400 – odnowienie Akademii Krakowskiej.\nPrzypomnij, z jakich ziem składała się Polska pod koniec rządów Kazimierza Wielkiego. Czym Rusini różnili się od Polaków w XIV w.?\nUnia polsko-węgierska\nPo śmierci Kazimierza Wielkiego królem Polski został jego siostrzeniec, król Węgier Ludwik (1370).\nPolacy nazywali go Ludwikiem Węgierskim lub Andegaweńskim, gdyż pochodził z francuskiej rodziny Andegawenów. Nowy król połączył Polskę i Węgry unią personalną. Unia to związek dwóch lub więcej państw, które łączą się dla wspólnych korzyści. Określenie „personalna” pochodzi stąd, że tylko osoba monarchy łączyła oba państwa. Każdy kraj nadal miał osobne urzędy, skarb, armię i prawa.\nLudwik Węgierski chciał, by dynastia Andegawenów rządziła Polską także po jego śmierci. Polskie rycerstwo zgodziło się oddać tron jednej z córek Ludwika w zamian za ograniczenie podatków wprowadzone przez przywilej koszycki.\nW 1382 r. Ludwik zmarł, a unia personalna Polski z Węgrami wygasła.\n1. Dlaczego unię polsko-węgierską z 1370 r. nazywamy unią personalną?\nLudwik Węgierski. Król nie był lubiany przez Polaków, gdyż nie nauczył się polskiego i niechętnie przyjeżdżał nad Wisłę. Obraz Jana Matejki.\nKról Jadwiga\nW 1384 r. królem Polski została córka Ludwika Węgierskiego, 10-letnia Jadwiga Andegaweńska. Zwykle nazywamy ją królową – tak jak żonę króla. Jednak Jadwiga miała wszystkie prawa polskiego monarchy."],"194":["Król Jadwiga i pogańska Litwa","Nowa władczyni była piękna i znakomicie wykształcona – znała pięć języków. Ledwo przybyła do Krakowa, możni panowie zaczęli szukać dla niej męża. Chcieli, by został nim władca obcego państwa. Małżeństwo w rodzinach monarchów było najlepszym sposobem zawarcia sojuszu, a 12-letnia dziewczynka uchodziła za dojrzałą do tego, by być żoną i matką.\n2. Co to znaczy, że Jadwiga została królem Polski? 3. Dlaczego możni panowie szukali męża dla Jadwigi?\nPogańska Litwa\nZa wschodnią granicą Polski leżało Wielkie Księstwo Litewskie. W XIV w. Litwini podbili ogromne tereny Rusi, które podlegały wtedy Tatarom. Napadali też na Polskę.\nKsięstwo było rozległym państwem, ale miało poważne problemy. Mieszkało w nim cztery razy więcej Rusinów niż Litwinów. Między obu narodowościami istniały znaczne różnice.\nLitwini należeli do ludów bałtyckich, tak jak Prusowie; byli poganami; nie znali pisma. Rusini byli Słowianami; od X w. wyznawali prawosławne chrześcijaństwo; znali pismo od X w.\nLitwę otaczali wrogowie: Wielkie Księstwo Moskiewskie chciało odebrać Litwinom wszystkie ziemie ruskie; państwo zakonu krzyżackiego dążyło do podboju Litwy; Tatarzy chcieli ponownie podporządkować sobie Ruś; Polska pragnęła położyć kres litewskim napadom.\nNajwiększe zagrożenie dla Litwy stanowili Krzyżacy. Raz lub dwa razy do roku organizowali krwawe wyprawy „misyjne”, które docierały pod Wilno i dalej.\n4. Wyjaśnij, jakie problemy przyniósł Litwie podbój Rusi. 5. Kto i dlaczego był wrogiem Litwy?\nJadwiga Andegaweńska (1374–1399). Córka króla Ludwika Węgierskiego, prawnuczka Władysława Łokietka, królowa Polski od 1384 r. Była powszechnie szanowana – nawet przez Krzyżaków. Broniła interesów Polski przed wielkim mistrzem zakonu, starała się też o pojednanie Władysława Jagiełły z jego kuzynem Witoldem. Lubiła książki; opłacała nawet kopistów, żeby je dla niej przepisywali. Dążyła do odnowienia uniwersytetu w Krakowie, co nastąpiło dopiero po jej śmierci. Malował Marcello Bacciarelli.\nKrólowa Jadwiga bardzo lubiła jabłka, gruszki, orzechy i torty. W specjalnym skarbczyku trzymała przyprawy i cukier, który był wtedy bardzo drogi."],"195":["Przyczyny i zawarcie unii polsko-litewskiej","Bojarzy – możni panowie i rycerze w Wielkim Księstwie Litewskim, a także w Wielkim Księstwie Moskiewskim.\nPrzyczyny unii polsko-litewskiej\nPolscy możnowładcy i litewscy bojarzy ustalili, że Jadwiga poślubi wielkiego księcia Litwy Jagiełłę, a Polska i Litwa zawrą unię.\nChoć państwa te były wrogami, a także różniły się językami, religią, ustrojem politycznym, rozwojem gospodarczym oraz obyczajami, możni polscy i litewscy spodziewali się po unii wielu korzyści.\nOczekiwane korzyści unii polsko-litewskiej. Polacy mieli nadzieję, że skończą się litewskie najazdy i wspólnymi siłami odzyskają utracone ziemie, zwłaszcza Pomorze Gdańskie. Polscy możni chcieli uzyskać ziemie i stanowiska na Litwie, a Kościół pragnął nawrócić ostatni pogański kraj Europy.\nLitwini liczyli na to, że zamienią wroga w sprzymierzeńca; wspólnymi siłami obronią się przed Krzyżakami; uzyskają polską pomoc przeciwko Moskwie; przyjmą chrzest od Polaków, a nie od znienawidzonych Krzyżaków; chrzest odbierze Krzyżakom pretekst do najazdów. Wielki książę miał nadzieję zostać królem Polski, a bojarzy chcieli otrzymać uprawnienia polskiego rycerstwa.\nOba państwa spodziewały się, że wzrośnie ich siła i znaczenie w Europie.\nTekst źródłowy. Jan Długosz pisał, że król polski z pomocą chrześcijańskich książąt pracował nad rycerzami i ludem, aby porzucili fałszywych bogów i przyjęli wiarę jednego Boga i chrześcijańską religię. Gdy część Litwinów się sprzeciwiała, Władysław kazał zgasić uznawany za wieczny ogień w Wilnie oraz zburzyć świątynię i ołtarz, na którym składano ofiary. Jan Długosz, Roczniki, czyli Kroniki sławnego Królestwa Polskiego, XV w.\nWyjaśnij, jak król wprowadzał na Litwie nową religię.\nZakon krzyżacki był wspólnym wrogiem obu państw, ale zagrażał im niejednakowo. Polska chciała tylko odzyskać utracone ziemie; Litwie groziło, że przestanie istnieć.\n6. Wyjaśnij, jakich korzyści spodziewała się po unii Polska, a jakich – Litwa.\nZawarcie unii\nW sierpniu 1385 r. poselstwa obu państw podpisały umowę w Krewie na Litwie o warunkach przyszłej unii. W zamian za rękę Jadwigi i polską koronę wielki książę Jagiełło obiecał: przyjąć chrzest wraz z poddanymi; odzyskać ziemie utracone przez Polskę; uwolnić polskich jeńców wojennych; przyłączyć Wielkie Księstwo Litewskie do Polski.\nChoć umowa mówiła o „przyłączeniu Litwy do Polski”, w praktyce oba państwa pozostały niezależne."],"196":["Unia polsko-litewska i odnowienie uniwersytetu","Polska i Litwa w XIV w. Mapa przedstawia Królestwo Polskie i Wielkie Księstwo Litewskie oraz ich sąsiadów, m.in. państwo zakonu krzyżackiego, Czechy, Węgry, Ruś i Wielkie Księstwo Moskiewskie. Polecenia: wymień główne miasta Wielkiego Księstwa Litewskiego; sprawdź w atlasie, do jakich państw dziś należą te miasta.\nŻeby doszło do unii, Jadwiga musiała poślubić 35-letniego „dzikiego barbarzyńcę”. Dla dobra Polski, Litwy i chrześcijaństwa królowa zgodziła się na małżeństwo z Jagiełłą.\nW początkach 1386 r. Polska i Litwa podpisały akt unii. Była to unia personalna, taka jak poprzednio z Węgrami.\nW lutym 1386 r. Jagiełło przyjął chrzest, na którym otrzymał imię Władysław. Potem poślubił Jadwigę i został koronowany na króla Polski. Związek obu państw przetrwał aż do 1795 r.\n7. Podaj warunki, na jakich Polska i Litwa zawarły unię. 8. Przedstaw wydarzenia, które doprowadziły do koronacji Jagiełły na króla Polski.\nOdnowienie uniwersytetu\nPo koronacji Władysław Jagiełło udał się na Litwę, gdzie wraz z polskimi duchownymi nawracał poddanych na chrześcijaństwo. Podobno sam przełożył na litewski modlitwę Ojcze nasz.\nW 1399 r. Jadwiga urodziła córeczkę, która przeżyła tylko trzy tygodnie. Kilka dni po jej śmierci 25-letnia królowa zmarła z powodu komplikacji po porodzie.\nWładysław Jagiełło (ok. 1351–1434). Wielki książę litewski, od 1386 r. król Polski i pierwszy monarcha z dynastii Jagiellonów. Po śmierci królowej Jadwigi odnowił uniwersytet w Krakowie. W 1410 r. dowodził wojskami polsko-litewskimi w bitwie pod Grunwaldem. Był wybitnym politykiem, a przy tym skromnym człowiekiem – na co dzień chodził w baranim kożuchu pokrytym tkaniną. Obraz Jana Matejki."],"197":["Odnowienie Akademii Krakowskiej – podsumowanie unii","Śmierć Jadwigi wstrząsnęła krajem. Lud kochał ją za dobroć, możni panowie szanowali ją za mądrość. Gdy chorowała, chłopi przynosili na Wawel kury i jajka, żeby ich królowa miała świeże wiejskie jedzenie.\nW testamencie Jadwiga zapisała swe klejnoty Akademii Krakowskiej, gdyż uczelnia podupadła po śmierci Kazimierza Wielkiego. W 1400 r. Władysław Jagiełło odnowił ją dzięki darowiźnie królowej. W XIX w., na cześć Jagiełły i Jadwigi, uczelnię nazwano Uniwersytetem Jagiellońskim.\n9. Wyjaśnij, jak doszło do odnowienia uniwersytetu w Krakowie.\nWładysław Jagiełło klęczy przed Matką Boską z Dzieciątkiem. Opiekunem monarchy jest św. Mikołaj, najbardziej popularny święty na Rusi. Fresk z kaplicy zamkowej w Lublinie, namalowany za życia króla w XV w.\nPytania i polecenia. A. Przedstaw sytuację Litwy przed zawarciem unii z Polską. B. Podaj przyczyny unii polsko-litewskiej. C. Wyjaśnij, czym królowa Jadwiga zasłużyła się dla Polski.\nTo, co najważniejsze. Unia personalna Polski z Węgrami (1370–1382) istniała za rządów króla Ludwika Węgierskiego.\nJadwiga Andegaweńska – królowa Polski w latach 1384–1399: w 1386 r. poślubiła wielkiego księcia Litwy Jagiełłę; przed śmiercią zapisała klejnoty Akademii Krakowskiej, którą Władysław Jagiełło odnowił w 1400 r.\nUnia Polski z Litwą (1386). Polska chciała położyć kres litewskim najazdom, odzyskać utracone ziemie; możni liczyli na ziemie i stanowiska na Litwie, Kościół pragnął nawrócić Litwinów. Litwa chciała zamienić wroga w sprzymierzeńca, obronić się przed Krzyżakami, uzyskać pomoc przeciw Moskwie, przyjąć chrzest od Polaków i odebrać Krzyżakom pretekst do najazdów; wielki książę chciał zostać królem Polski, a bojarzy uzyskać uprawnienia polskiego rycerstwa. Oba państwa liczyły na wzrost siły i znaczenia.\nJak zawarto unię: umowa w Krewie o warunkach przyszłej unii (1385); zawarcie unii personalnej (1386); chrzest Władysława Jagiełły, ślub z Jadwigą i koronacja na króla Polski (1386)."],"198":["Wielka wojna z zakonem krzyżackim – przyczyny","36. Wielka wojna z zakonem krzyżackim\nOś czasu: 1309 – zajęcie Pomorza Gdańskiego przez Krzyżaków; 1331 – bitwa pod Płowcami; 1343 – pokój wieczysty w Kaliszu; 1409–1411 – wielka wojna z zakonem krzyżackim; 1410 – bitwa pod Grunwaldem; 1411 – pierwszy pokój toruński.\nPrzyczyny wojny\nW XIV w. państwo zakonu krzyżackiego stało się potęgą. Krzyżacy czerpali pokaźne zyski z handlu przez port w Gdańsku, a za uzyskane pieniądze budowali zamki, kościoły, szpitale, młyny i przystanie. Zamek w Malborku – stolica zakonnego państwa – był jedną z najpotężniejszych warowni w Europie.\nJednak unia polsko-litewska oraz chrzest Litwy zmieniły na niekorzyść sytuację zakonu: jego przeciwnicy połączyli siły; państwo zakonne stało się niepotrzebne, bo Prusowie od dawna wyznawali chrześcijaństwo, a Litwini przyjęli chrzest od Polaków; nawrócenie Litwy przez Polskę kompromitowało zakon, który od ponad 100 lat prowadził „misje” na Litwie.\nAby poprawić położenie, Krzyżacy oczerniali Litwę i Polskę na Zachodzie. Rozpowiadali, że Jagiełło to fałszywy chrześcijanin, a jego kraj pozostał pogański. Nadal organizowali zbrojne wyprawy „misyjne” w głąb Litwy, postępując nieraz bardzo okrutnie.\nPolacy walczyli w obronie Litwy, choć oficjalnie państwo polskie zachowywało pokój z zakonem. Był on nietrwały, gdyż Polska chciała odzyskać Pomorze Gdańskie, a Krzyżacy nie zamierzali go oddać.\nWarownia – budowla obronna.\nPolecenia: wyjaśnij, w jaki sposób Polska utraciła Pomorze Gdańskie; przypomnij postanowienia pokoju wieczystego w Kaliszu."],"199":["Infografika – Zamek w Malborku","INFOGRAFIKA. Zamek w Malborku.\nMalbork to po niemiecku Marienburg, czyli zamek Maryi. W 1309 r. zamek w Malborku – nie miasto! – stał się stolicą państwa zakonnego.\nTwierdza imponowała każdemu, kto ją zobaczył. Była to jedna z najpotężniejszych budowli obronnych w Europie, większa od wielu średniowiecznych miast. Zamkowe spiżarnie mogły pomieścić żywność na dwa lata oblężenia.\nNa fotografii zaznaczono elementy kompleksu zamkowego numerami 1–8; ich opisy znajdują się na następnej stronie."],"200":["Zamek w Malborku – elementy fortyfikacji","Infografika „Zamek w Malborku” – opis elementów.\n1. Przedzamcze albo Zamek Niski. W jego budynkach mieściły się magazyny żywności, zbrojownie i warsztaty rzemieślnicze.\n2. Zamek Średni. Tu odbywały się uczty z udziałem zagranicznych gości.\n3. Wielki refektarz, czyli główna jadalnia. Mieścił 400 osób.\n4. Pałac wielkiego mistrza.\n5. Dziedziniec Zamku Średniego.\n6. Drewniany most nad fosą między Zamkiem Wysokim a Średnim.\n7. Baszty mostowe. Między nimi znajdowała się brama, do której prowadził most przez rzekę Nogat.\n8. Mury obronne.\n9. Wieża główna.\n10. Kościół Najświętszej Marii Panny. Pod nim znajdowała się kaplica św. Anny, gdzie chowano wielkich mistrzów.\n11. Zamek Wysoki. Był otoczony fosami i kilkoma pierścieniami murów obronnych.\n12. Gdanisko, tj. wieża toaletowa – nieczystości spadały do fosy. Pełniła też funkcje obronne.\nDlaczego zamek w Malborku imponował każdemu, kto go zobaczył? W jaki sposób Krzyżacy zadbali o obronność swojej stolicy?"],"201":["Wybuch wielkiej wojny z zakonem","Tekst źródłowy. Polski poseł ostrzegał wielkiego mistrza w Malborku, aby przestał straszyć Litwę wojną. Jeśli zakon napadnie na Litwę, król Polski najedzie Prusy. Wielki mistrz uznał Litwinów za wrogów, a Polaków – jeśli ich wesprą – także za przeciwników. Jan Długosz, Roczniki, czyli Kroniki sławnego Królestwa Polskiego, XV w.\nCo się stanie, zdaniem polskiego posła, jeśli wielki mistrz wypowie wojnę Litwie? Dlaczego Polacy tak postąpią?\nPo zdobyciu zamku w Kownie na pogańskiej jeszcze Litwie Krzyżacy śpiewają pieśń triumfu „Chrystus zmartwychwstał” (1362). Niemiecki rysownik z XIX w. ukazał tę scenę jako moment chwały zakonu.\nW 1409 r. wybuchło powstanie przeciw Krzyżakom na Żmudzi, należącej już do zakonu. Powstańców poparli Litwini. Gdy zakon zagroził im wojną, polski poseł oświadczył w Malborku, że Polska stanie w obronie Litwy.\nWówczas Krzyżacy postanowili rozprawić się najpierw z Polską – wypowiedzieli jej wojnę i zajęli ziemię dobrzyńską. Tak zaczęła się wielka wojna Polski i Litwy z zakonem krzyżackim. Trwała ona od 1409 do 1411 r.\n1. Dlaczego i w jaki sposób Krzyżacy starali się rozerwać unię polsko-litewską? 2. Kto i dlaczego rozpoczął wojnę w 1409 r.?\nBitwa pod Grunwaldem. Obraz Tadeusza Popiela i Zygmunta Rozwadowskiego z 1910 r."],"202":["Bitwa pod Grunwaldem – siły obu armii","Bitwa pod Grunwaldem\nLatem 1410 r. król Władysław Jagiełło na czele połączonych wojsk Polski i Litwy wkroczył do państwa zakonnego. Jego armia maszerowała prosto na Malbork.\nKierunek ataku zaskoczył Krzyżaków. Spodziewali się wojny o Pomorze Gdańskie, a nie uderzenia w samo serce swego państwa. Pospiesznie wyruszyli na spotkanie sił polsko-litewskich.\nArmia polsko-litewska: ok. 30 tysięcy ludzi – Polacy, Litwini, Rusini, a także Czesi i Tatarzy.\nArmia krzyżacka: ok. 20 tysięcy ludzi – 250 Krzyżaków, rycerze mieszkający w państwie zakonnym, wśród nich Polacy, oraz „goście”, czyli rycerze z Zachodu i Niemiec.\nObie armie spotkały się 15 lipca 1410 r. na Mazurach. Doszło tam do wielkiej bitwy pod Grunwaldem.\nRankiem tego dnia Władysław Jagiełło wysłuchał dwóch mszy. Nie spieszył się, gdyż jego wojska odpoczywały w cieniu lasów. Krzyżacy stali w zbrojach w otwartym polu, gdzie dokuczał im lipcowy skwar.\nWielki mistrz przysłał więc królowi dwa miecze, żeby się „nie chował w lasach i gajach” i „nie odsuwał walki na potem”. Polski kronikarz z XV w. uznał ten gest za obraźliwy. Dziś historycy uważają, że była to zachęta do walki świadcząca o szacunku dla przeciwnika.\nCzłonkowie bractwa rycerskiego w strojach Krzyżaków przybywają pod Grunwald. Co roku w lipcu odbywa się tam rekonstrukcja bitwy."],"203":["Bitwa pod Grunwaldem i pierwszy pokój toruński","Jagiełło przyjął miecze, po czym dał rozkaz do ataku. Polscy rycerze odśpiewali wówczas pieśń Bogurodzica.\nBitwa miała dramatyczny przebieg. To jedna, to druga strona zyskiwała przewagę. W pewnej chwili upadła na ziemię chorągiew Królestwa Polskiego. Krzyżacy poczuli się pewni zwycięstwa. Przedwcześnie, bo król posłał do walki nowe siły.\nWielki mistrz uznał, że ma przed sobą wszystkie wojska Jagiełły. Postanowił rozstrzygnąć bitwę jednym uderzeniem. Sam poprowadził do ataku najlepsze oddziały zakonu – prawie jedną trzecią armii.\nAle król miał w odwodzie jazdę i piechotę. Ich natarcie przesądziło o wyniku bitwy.\nNa polach Grunwaldu Krzyżacy ponieśli straszliwą klęskę. Poległ wielki mistrz zakonu i prawie wszyscy najwyżsi dostojnicy państwa. Krzyżacka potęga została raz na zawsze złamana.\n3. Porównaj siły polskie i krzyżackie w bitwie pod Grunwaldem. 4. Dlaczego wielki mistrz przysłał Jagielle dwa miecze? 5. Co zadecydowało o wyniku bitwy pod Grunwaldem?\nRękopis Bogurodzicy (1407). Jest to najstarsza polska pieśń religijna – pochodzi z XIII lub XIV w.\nOdwód – rezerwowy oddział wojska.\nTekst źródłowy. Jan Długosz opisał, jak wielka chorągiew króla polskiego z białym orłem upadła pod naporem wrogów, ale polscy rycerze natychmiast ją podnieśli i umieścili na miejscu, nie dopuszczając do jej zniszczenia. Potem zaatakowali wrogów i rozbili ich kompletnie. Jan Długosz, Roczniki, czyli Kroniki sławnego Królestwa Polskiego, XV w.\nWyjaśnij, jak zareagowali polscy rycerze na upadek chorągwi Królestwa Polskiego.\nPierwszy pokój toruński\nKlęska zakonu wywarła ogromne wrażenie w Europie. Nikt się nie spodziewał, że Polacy i Litwini pokonają armię, która uchodziła za niezwyciężoną.\nDziesięć dni po bitwie armia polsko-litewska stanęła pod Malborkiem. Ale dwumiesięczne oblężenie krzyżackiej stolicy zakończyło się niepowodzeniem. Zamek okazał się nie do zdobycia.\nMimo to Krzyżacy nie mieli szans na zwycięstwo w wojnie. Obie strony postanowiły ją więc zakończyć. W 1411 r. podpisały w Toruniu pierwszy pokój toruński, na mocy którego Polska odzyskała tylko niewielką ziemię dobrzyńską, a Litwa – Żmudź. Pomorze Gdańskie pozostało w rękach Krzyżaków. Musieli jednak zapłacić Polsce ogromne odszkodowanie wojenne.\nMogło się wydawać, że po wspaniałym zwycięstwie Polska i Litwa uzyskały niewielkie korzyści. W rzeczywistości przegrana wojna bardzo poważnie osłabiła zakon."],"204":["Skutki wielkiej wojny z zakonem","Przegrana wojna bardzo poważnie osłabiła zakon. Jej koszty zachwiały gospodarką krzyżackiego państwa. Przestało się ono powiększać i już nigdy nie wróciło do dawnej świetności.\n6. Dlaczego obie strony zdecydowały się zawrzeć pokój? 7. Podaj postanowienia pierwszego pokoju toruńskiego.\nMapa „Wielka wojna z zakonem (1409–1411)” przedstawia kierunki marszu i działań wojsk polskich, litewskich i krzyżackich, miejsca koncentracji wojsk, ziemie podporządkowane Polsce, granice ziem utraconych przez zakon w 1411 r. i oblężenie Malborka. Polecenia: gdzie spotkały się wojska polskie i litewskie; skąd armia krzyżacka wyruszyła pod Grunwald; wskaż obszar przyłączony do Polski w wyniku pierwszego pokoju toruńskiego.\nPytania i polecenia. A. Przedstaw przyczyny wielkiej wojny z zakonem krzyżackim. B. Omów przebieg bitwy pod Grunwaldem. C. Czy zwycięstwo pod Grunwaldem przyniosło Polsce i Litwie niewielkie korzyści? Uzasadnij odpowiedź.\nTo, co najważniejsze. Państwo zakonu krzyżackiego w XIV w. stało się potęgą, a jego stolicą był zamek w Malborku.\nNastępstwa unii polsko-litewskiej: przeciwnicy zakonu połączyli siły; państwo zakonne przestało być potrzebne; Krzyżacy starali się rozerwać unię i nadal podbijali Litwę.\nPolacy po zawarciu unii bronili Litwy mimo pokoju wieczystego Polski z zakonem i chcieli odzyskać Pomorze Gdańskie.\nWielka wojna (1409–1411). Przyczyny: Litwa poparła antykrzyżackie powstanie na Żmudzi; Polska zapowiedziała obronę Litwy przed Krzyżakami. Główne wydarzenie: armia polsko-litewska dowodzona przez Władysława Jagiełłę zadała Krzyżakom klęskę pod Grunwaldem (1410). Pierwszy pokój toruński (1411): Polska odzyskała ziemię dobrzyńską, a Litwa Żmudź; Krzyżacy musieli zapłacić Polsce ogromne odszkodowanie wojenne."],"205":["Synowie Jagiełły – monarchia elekcyjna","37. Synowie Jagiełły\nOś czasu: 1434 – koronacja Władysława Warneńczyka na króla Polski; 1444 – bitwa pod Warną; 1447 – koronacja Kazimierza Jagiellończyka na króla Polski; 1454–1466 – wojna trzynastoletnia; 1466 – drugi pokój toruński.\nPrzypomnij: kiedy i dlaczego Polska zawarła unię z Węgrami? Jakie były postanowienia pierwszego pokoju toruńskiego?\nPolska monarchią elekcyjną\nKażda monarchia może być dziedziczna albo elekcyjna. W monarchii dziedzicznej po śmierci władcy tron dziedziczy jego syn lub inny krewny. W monarchii elekcyjnej król pochodzi z wyboru.\nMonarchia patrymonialna była ustrojem, w którym monarcha uważał państwo za swoją własność i sam decydował o wszystkich jego sprawach – także o następstwie tronu. Na ogół przekazywał go synowi. Była więc zarazem monarchią dziedziczną.\nPolska była od 966 r. monarchią dziedziczną. Po wyborze Jagiełły na polski tron stała się monarchią elekcyjną. Odtąd wyboru króla dokonywali możnowładcy, czyli najbogatsi rycerze.\nWładysław Jagiełło zmarł w 1434 r., przeziębił się, słuchając śpiewu słowików. W tym samym roku możnowładcy wybrali jego syna, 10-letniego Władysława, na króla Polski.\n1. Wyjaśnij, czym się różniła monarchia elekcyjna od dziedzicznej.\nKról Polski w stroju turniejowym, ozdobionym herbami państwa. Kopia francuskiej ryciny z XV w.\nDruga unia z Węgrami\nW XIV w. w Europie południowo-wschodniej zaczęli zagrażać Turcy osmańscy, nazwa pochodzi od sułtana o imieniu Osman. Ponieważ wyznawali islam, chrześcijanie uważali ich za „niewiernych”. Turcy tak samo myśleli o „niewiernych” chrześcijanach.\nSułtan – władca Turcji osmańskiej."],"206":["Druga unia z Węgrami i Władysław Warneńczyk","Turcy osmańscy zajęli znaczne tereny w Azji i Europie. Utworzyli na nich imperium osmańskie. W XV w. zagrozili Węgrom.\nPolscy możni uważnie przyglądali się sytuacji na Węgrzech. Gdy zapanowało tam bezkrólewie, wysunęli króla Polski Władysława jako kandydata do węgierskiego tronu. Chcieli zawrzeć unię z Węgrami i wspólnymi siłami wypędzić Turków z Europy. Mieli nadzieję, że dzięki temu wzrośnie międzynarodowe znaczenie Polski.\nW 1440 r. 16-letni monarcha został koronowany na króla Węgier. Polska i Węgry po raz drugi połączyły się unią personalną.\n2. Dlaczego polscy możni chcieli zdobyć tron Węgier dla króla Władysława?\nWładysław Warneńczyk\nW 1443 r. Władysław rozpoczął wojnę z potężnym imperium osmańskim. Faktycznym dowódcą wojsk chrześcijańskich był jednak nie król, lecz znakomity węgierski wódz János Hunyady.\nJanczarzy, czyli żołnierze najlepszych oddziałów tureckiej piechoty. Janczarami zostawali chłopcy odebrani chrześcijańskim rodzicom i wychowani na fanatycznych muzułmanów. Ilustracja z początków XVI w.\nKról Władysław w zbroi, z mieczem w dłoni pędzi do ataku w bitwie pod Warną. Tak wyobrażał ją sobie Jan Matejko."],"207":["Bitwa pod Warną i inkorporacja Prus","Tekst źródłowy. Anonimowy autor turecki opisywał, że Władysław, zwiedziony pokusą szatana i zbyt ufny w swe siły, ruszył przeciw armii tureckiej. Gdy dotarł do skraju szyku, koń się potknął, król spadł na twarz, a janczar Kodża Hyzyr uciął mu głowę i zaniósł ją sułtanowi Muradowi. Głowę zatknięto na lancę i podniesiono, wołając: „Ta głowa jest głową króla”. Anonimowy autor turecki, Kronika, XV w.\nDlaczego, zdaniem autora tekstu, król uderzył na Turków? W jaki sposób zginął Władysław? Co zrobił sułtan, gdy się dowiedział o śmierci króla? Lanca – broń podobna do włóczni, używana przez jazdę.\nDowodzona przez Hunyadyego armia w krótkim czasie odniosła kilka świetnych zwycięstw. Sułtan zawarł wówczas z królem 10-letni pokój, korzystny dla Węgier (1444).\nZakończeniu wojny sprzeciwił się wysłannik papieża, gdyż zależało mu na wyparciu Turków z Europy. Namówił Władysława do złamania warunków pokoju, twierdząc, że jest nieważny, bo zawarto go z „niewiernymi”. Król ruszył przeciwko Turkom na czele 20-tysięcznej armii węgierskiej, wspieranej przez nieliczne oddziały Polaków.\nJesienią 1444 r. doszło do bitwy pod Warną, w dzisiejszej Bułgarii. Na czele 60-tysięcznej armii tureckiej stał sam sułtan.\nMimo przewagi liczebnej Turków Węgrzy byli bliscy zwycięstwa. Jednak Władysław lekkomyślnie poprowadził oddział 500 rycerzy do ataku na doborowe siły sułtana. Król zginął, a na wieść o jego śmierci armia węgierska poszła w rozsypkę. Bitwa zakończyła się klęską Węgrów.\nPoległy władca otrzymał przydomek Warneńczyk. Jego śmierć położyła kres unii polsko-węgierskiej.\nPo zwycięstwie Turcy rozpoczęli nowe podboje w Europie. W 1453 r. zdobyli Konstantynopol, zmienili jego nazwę na Stambuł i przenieśli tam stolicę swego państwa. Cesarstwo bizantyjskie przestało istnieć.\n3. Z jakiego powodu król zerwał pokój z sułtanem? 4. Przedstaw skutki klęski chrześcijan pod Warną.\nInkorporacja Prus\nW 1447 r. królem Polski został młodszy brat Władysława Warneńczyka, Kazimierz Jagiellończyk. Za jego rządów wybuchła wojna Polski z zakonem krzyżackim. Jej głównymi przyczynami były dążenie Polski do odzyskania Pomorza Gdańskiego oraz niezgoda mieszkańców państwa zakonnego na krzyżackie rządy.\nOd przegranej w wielkiej wojnie Krzyżacy mieli stale za mało pieniędzy. Żeby je zdobyć, nakładali wysokie podatki i inne opłaty. Budziły one niezadowolenie mieszczan i rycerzy, którzy zazdrościli też uprawnień polskiemu rycerstwu."],"208":["Inkorporacja Prus i wojna trzynastoletnia","W 1440 r. mieszczanie i rycerze państwa zakonnego założyli Związek Pruski, który sprzeciwiał się rządom Krzyżaków.\nW 1454 r. Związek Pruski wypowiedział posłuszeństwo wielkiemu mistrzowi. W Prusach wybuchło powstanie przeciwko Krzyżakom. Powstańcy opanowali wszystkie zamki zakonne z wyjątkiem trzech, wśród nich Malborka. Kazimierz Jagiellończyk wydał akt inkorporacji, czyli wcielenia Prus do Polski. Po akcie inkorporacji Polska wypowiedziała wojnę zakonowi krzyżackiemu.\nAkt inkorporacji Prus do Polski. U dołu przywieszono odciski pieczęci miast pruskich, które w ten sposób zatwierdziły tekst dokumentu.\nPospolite ruszenie – siła zbrojna złożona ze szlachty. Na wezwanie króla każdy szlachcic musiał się stawić konno i zbrojnie w wyznaczonym miejscu.\n5. Podaj przyczyny konfliktu między Polską a zakonem krzyżackim. 6. Omów wydarzenia, które doprowadziły do wybuchu wojny Polski z zakonem.\nWojna trzynastoletnia\nWiosną 1454 r. zdawało się, że triumf Polaków jest bliski. Radość okazała się przedwczesna. Wojna trwała 13 lat i dlatego została nazwana wojną trzynastoletnią.\nZakon opłacił żołnierzy najemnych, którzy byli zdyscyplinowani i walczyli nowocześnie, używając artylerii i oddziałów piechoty. Polską armię tworzyło niezdyscyplinowane i przestarzałe pospolite ruszenie szlachty. We wrześniu 1454 r. polska armia poniosła klęskę pod Chojnicami. Wkrótce potem zakon odzyskał znaczną część swego państwa.\nKazimierz Jagiellończyk zrozumiał, że jeśli chce wygrać wojnę, musi mieć pieniądze. Uzyskał je dzięki podatkom, pożyczkom oraz wsparciu Gdańska i innych miast pomorskich. Za gotówkę zwerbował wojska najemne, a nawet wykupił zamek w Malborku z rąk krzyżackich najemników.\nW 1462 r. Polacy odnieśli zwycięstwo pod Świecinem. Był to przełomowy moment wojny; odtąd Krzyżacy doznawali kolejnych niepowodzeń. Wreszcie w 1466 r. obie strony zawarły drugi pokój toruński.\nKazimierz Jagiellończyk (1427–1492). Młodszy syn Władysława Jagiełły, od 1440 r. wielki książę litewski, od 1447 r. król Polski. Panował do śmierci, tj. przez 45 lat. Był wybitnym politykiem – przewidującym i zdolnym do ustępstw. Miał trzynaścioro dzieci, a czterech jego synów zostało królami. Uwielbiał polowania. Tradycja głosi, że jako ostatni polski monarcha nie umiał czytać ani pisać. Obraz Jana Matejki."],"209":["Drugi pokój toruński – skutki wojny trzynastoletniej","Drugi pokój toruński (1466). Polska odzyskała Pomorze Gdańskie, ziemię chełmińską i michałowską; uzyskała Malbork, Elbląg i Warmię, których nigdy wcześniej nie posiadała; podporządkowała sobie państwo krzyżackie, które było odtąd jej lennem, nazywanym Prusami Zakonnymi.\nTereny odzyskane i uzyskane przez Polskę nazwano Prusami Królewskimi, gdyż władał nimi król.\nOdzyskanie Gdańska otworzyło Polsce drogę handlową na Zachód. Szlachta i kupcy mogli teraz czerpać duże zyski z handlu zbożem, drewnem i innymi towarami.\n7. Na czym polegała wyższość armii krzyżackiej nad polską w 1454 r.? 8. Co zrobił Kazimierz Jagiellończyk, by wygrać wojnę?\nLenno – w stosunkach między państwami: ziemie zależne od innego państwa.\nMapa „Wojna trzynastoletnia i drugi pokój toruński” przedstawia granice państwa zakonnego w 1454 r., Polskę i jej lenna w 1454 r., nabytki Polski w 1466 r., lenna polskie uzyskane w 1466 r. oraz ważniejsze bitwy. Polecenie: wskaż na mapie Prusy Królewskie i Prusy Zakonne.\nPytania i polecenia. A. Przedstaw podboje Turków osmańskich do 1453 r. B. Omów przebieg wojny trzynastoletniej. C. Wytłumacz, jakie korzyści przyniósł Polsce drugi pokój toruński.\nTo, co najważniejsze. Ustrój Polski: po wyborze Jagiełły na polski tron państwo z monarchii dziedzicznej stało się monarchią elekcyjną.\nWładysław Warneńczyk – król Polski w latach 1434–1444: w 1440 r. został królem Węgier, a Polska i Węgry zawarły unię personalną; zginął w bitwie z Turkami pod Warną (1444).\nKazimierz Jagiellończyk – król Polski w latach 1447–1492. Stoczył wojnę trzynastoletnią z Krzyżakami (1454–1466). Przyczyny: dążenie Polski do odzyskania Pomorza Gdańskiego oraz niezgoda mieszkańców państwa zakonnego na krzyżackie rządy. Bezpośrednią przyczyną był akt inkorporacji Prus do Polski (1454). Drugi pokój toruński (1466): przyłączenie Prus Królewskich do Polski; państwo zakonne lennem Polski jako Prusy Zakonne."],"210":["Od rycerstwa do szlachty – przywileje szlacheckie","38. Od rycerstwa do szlachty\nOś czasu: 1374 – przywilej koszycki; 1422 – przywilej czerwiński; 1430 i 1433 – przywileje jedlneńsko-krakowskie; 1454 – przywilej cerekwicko-nieszawski; 1505 – konstytucja Nihil novi.\nPrzypomnij: czym były średniowieczne stany? Wymień cztery stany średniowiecza.\nPrzywileje szlacheckie\nW czasach Piastów państwem rządził król. Np. Kazimierz Wielki ustanawiał prawa, decydował o podatkach oraz o wojnie i pokoju, a zbuntowanego możnowładcę kazał zagłodzić na śmierć.\nZa rządów Ludwika Węgierskiego rycerze zaczęli się domagać większych praw i mniejszych podatków. Monarcha spełnił ich żądania, gdyż chciał, by w przyszłości wybrali na króla jego córkę. W 1374 r. na zjeździe w Koszycach, na Słowacji, w zamian za koronę dla córki wystawił rycerstwu przywilej, nazywany potem przywilejem koszyckim. Na jego mocy stan rycerski miał płacić tylko jeden niewielki podatek.\nOdtąd rycerze wysuwali swe żądania wtedy, gdy władca czegoś od nich potrzebował.\nPrzywileje nadawane rycerzom nazywamy przywilejami szlacheckimi, gdyż dzięki nim w XV w. rycerstwo przekształciło się w szlachtę. Różnica polegała na tym, że rycerze nie mieli wpływu na rządy państwem, a szlachta taki wpływ uzyskała.\nPrzywileje szlacheckie ograniczyły władzę monarchy. Przywilej koszycki zmniejszył jego dochody. Z kolei na mocy przywileju cerekwicko-nieszawskiego (1454) król musiał uzyskać zgodę szlachty za każdym razem, gdy chciał nałożyć nowy podatek lub zwołać pospolite ruszenie. Jeśli takiej zgody nie otrzymał, nie miał ani pieniędzy, ani wojska.\nW ten sposób w drugiej połowie XV w. szlachta zaczęła współrządzić państwem.\nPrzywilej – królewski dokument, który przyznawał wyjątkowe prawa jednemu ze stanów.\nNa ilustracji z XVI w. szlachcic otrzymuje od króla herb. Był to znak rozpoznawczy każdego rycerza, a potem szlachcica."],"211":["Najważniejsze przywileje szlacheckie i sejmiki","Najważniejsze przywileje szlacheckie.\nKoszyce 1374 – Ludwik Węgierski: król wprowadza tylko jeden stały i niewielki podatek.\nCzerwińsk 1422 – Władysław Jagiełło: bez wyroku sądu król nie może zająć majątku szlachcica.\nJedlnia 1430 i Kraków 1433 – Władysław Jagiełło: bez wyroku sądu król nie może uwięzić szlachcica.\nCerekwica i Nieszawa 1454 – Kazimierz Jagiellończyk: król nie nałoży nowych podatków ani nie zwoła pospolitego ruszenia bez zgody szlachty.\n1. Co to jest przywilej? 2. Wyjaśnij korzyści wynikające z przywileju koszyckiego dla rycerstwa i dla króla. 3. Czym się różniła szlachta od rycerstwa?\nSejmiki i sejm walny\nKiedy król chciał uzyskać zgodę szlachty na podatek albo pospolite ruszenie, zwoływał sejmiki szlacheckie. Były to zjazdy szlachty danego województwa, np. sandomierskiego, albo ziemi, np. dobrzyńskiej.\nSejmik w kościele. Szlachta zbierała się w kościołach, gdyż mogły pomieścić setki osób. Rysunek z XVIII w."],"212":["Sejmiki, sejm walny i konstytucja Nihil novi","W Polsce i na Litwie zbierało się około 70 sejmików. Każdy podejmował decyzje przez głosowanie. Jeśli sejmik nie zgodził się na podatek, władca nie miał prawa go nałożyć.\nSejmiki posyłały do króla swoich przedstawicieli, czyli posłów. To oni powiadamiali monarchę o decyzjach sejmików. Brali też udział w spotkaniach króla z biskupami i urzędnikami, którzy doradzali mu w sprawach państwa.\nW drugiej połowie XV w. te spotkania przekształciły się w sejm walny – instytucję decydującą o najważniejszych sprawach państwa, takich jak wojna i pokój, liczebność wojska oraz podatki.\nSejm walny składał się z trzech części, tzw. stanów sejmujących: króla, izby senatorskiej i izby poselskiej. Po uroczystym otwarciu sejmu każda izba obradowała osobno.\nStany sejmujące sejmu walnego. 1. Król – zwoływał sejm, podawał tematy obrad i przedstawiał własne projekty ustaw. 2. Izba senatorska zwana też senatem – zasiadali w niej senatorowie, czyli najważniejsi dostojnicy państwa i Kościoła katolickiego; zostawali nimi tylko magnaci, dawni możnowładcy. 3. Izba poselska – składała się z posłów szlacheckich wybranych przez sejmiki.\nSejm walny na rycinie z XVII w. Król i senatorowie siedzieli, posłowie musieli stać. Kobiety nie uczestniczyły ani w sejmie, ani w sejmikach.\nWalny – tu: ogólny, powszechny. Konstytucja – w dawnej Polsce: ustawa sejmu.\nZ początku do przyjęcia ustawy sejmowej wystarczała zgoda króla i senatu. Jednak w 1505 r. sejm przyjął konstytucję Nihil novi, po łacinie „nic nowego”. Głosiła ona, że sejm nie może uchwalić „nic nowego” bez zgody wszystkich trzech stanów sejmujących. Każdą ustawę musiała więc zatwierdzić także izba poselska. Odtąd szlachta nie tylko współrządziła państwem, lecz także współdecydowała o prawach uchwalanych przez sejm.\n4. Czym były i czym się zajmowały sejmiki? 5. Kiedy i w jaki sposób powstał sejm walny? 6. Wyjaśnij, jaką zmianę w sejmie walnym wprowadziła konstytucja Nihil novi.\nTekst źródłowy. Konstytucja Nihil novi z 1505 r. stanowiła, że ogólne prawa i ustawy publiczne nie mogą być stanowione bez wspólnego zezwolenia senatorów i posłów ziemskich. Pytanie: kto musi zatwierdzić każdą uchwałę sejmu?"],"213":["Infografika – Polska szlachta","INFOGRAFIKA. Polska szlachta.\nSzlachta współrządziła państwem, była zwolniona od większości podatków i sprawowała urzędy państwowe. Oto szlachcic i szlachcianka z drugiej połowy XVI w.\nHerb szlachecki o nazwie Leliwa. Używało go kilkaset rodów, tzn. wielkich rodzin.\nElementy stroju szlachcica: 1. Magierka – filcowa czapka węgierskiego pochodzenia, ozdobiona kitą z czaplich piór. 2. Delia – peleryna spinana pod szyją, zdobiona listwami, tj. paskami, i guzami ze złota, tłoczonego srebra lub cyny. 3. Żupan – długa suknia noszona pod delią albo jako osobny strój; od szyi do pasa była zapinana na guzy, tj. ozdobne guziki. 4. Metalowy pas. 5. Rapcie – dwa paski przyczepione do pasa i podtrzymujące szablę, drugi jest pod delią. 6. Szabla w pochwie. 7. Obcisłe spodnie wpuszczane w cholewy butów. 8. Skórzane buty. 9. Ostrogi. Szlachcic kłuł nimi boki konia, by zmusić go do szybszego biegu."],"214":["Jak działał sejm walny? Szlachta a mieszczaństwo","Jak działał sejm walny?\n1. Król zawiadamiał szlachtę o terminie i miejscu sejmu. Podawał też tematy obrad, np. nowy podatek.\n2. Sejmiki wybierały posłów na sejm i dawały im instrukcje, jak mają tam głosować, np. „nie ważcie się poprzeć nowego podatku”.\n3. Po uroczystym rozpoczęciu sejmu urzędnik królewski przedstawiał projekt nowego prawa, np. „podatek musi być wyższy niż dwa lata temu, bo państwu grozi wojna”. Posłowie też mogli zgłaszać własne projekty.\n4. Izba poselska – bez króla i senatorów – dyskutowała nad projektem. W końcu zatwierdzała tekst projektu. Bywało, że posłowie głosowali wbrew instrukcjom, „zgadzamy się dla dobra ojczyzny, jakoś się wytłumaczymy na sejmiku”.\n5. Posłowie przedstawiali zatwierdzony projekt senatorom i królowi. Ci zgłaszali swoje poprawki i uchwalali nowe prawo.\n6. Do przyjęcia każdego nowego prawa była potrzebna zgoda wszystkich trzech stanów sejmujących. Tylko gdy nastąpiła, prawo zaczynało obowiązywać w całym państwie.\n7. Wyjaśnij, czym podczas obrad sejmu zajmowali się posłowie, a czym – król i senatorowie.\nSzlachta a mieszczaństwo\nZa rządów Kazimierza Wielkiego w Polsce zaczęła powstawać monarchia stanowa. Nazywamy tak ustrój państwa, w którym władzę króla ograniczają przywileje stanów. W XIV-wiecznej Europie o przywileje zabiegały dwa stany: rycerstwo i mieszczaństwo.\nW Polsce, inaczej niż na Zachodzie, monarchia stanowa ostatecznie nie powstała. Przywileje zdobył u nas tylko jeden stan: szlachta.\nStało się tak dlatego, że skłócone polskie miasta nie umiały wspólnie bronić swoich praw. Mieszczanie nie mogli więc głosować w sejmie ani w sejmikach. Państwo zaczęło służyć interesom szlachty. Sejm m.in. zakazał mieszczanom posiadania ziemi, żeby nie konkurowali ze szlachtą w handlu zbożem.\nUstrój Polski od XVI do XVIII w. możemy określić jako monarchiczno-szlachecki: król sprawował najwyższą władzę, ale państwem współrządziła szlachta. Zasiadała w sejmie i sejmikach, sprawowała urzędy państwowe, posiadała ziemię i podporządkowała sobie chłopów. Szlachcic mógł skazać swojego poddanego na chłostę, a nawet na śmierć.\nKonie przed warsztatem kowala, który przybijał im podkowy. Rycina z 1505 r. pokazuje ówczesny Kraków."],"215":["Monarchia szlachecka – podsumowanie","Szlachta uważała, że należą się jej wszystkie te prawa, gdyż naraża życie w obronie ojczyzny. Ale, jak wiemy, szlacheckie pospolite ruszenie było niewiele warte.\nCałkowita przewaga jednego stanu nad innymi miała fatalne skutki dla losów państwa. Opowiemy o tym w następnej książce.\n8. Czym była monarchia stanowa? 9. Dlaczego w Polsce nie powstała monarchia stanowa?\nKiedy szlachcic zwracał się do drugiego szlachcica, mówił „panie bracie” albo „waszmość”. Żart: „Od dziś możesz do mnie mówić: waszmość Napoleonie”.\nSejm walny. Król oraz senatorowie duchowni i świeccy siedzą po bokach tronu. U dołu stoją posłowie na sejm. Wokół nich są widoczne herby Polski, Litwy oraz ziem obu państw. Rycina z początków XVI w.\nPytania i polecenia. A. Omów prawa szlachty, które zyskała ona dzięki przywilejom i konstytucji Nihil novi. B. Wyjaśnij, jak po 1454 r. król mógł nałożyć nowy podatek. C. Co to znaczy, że ustrój Polski od XVI do XVIII w. można nazwać monarchiczno-szlacheckim?\nTo, co najważniejsze. Przywileje szlacheckie: dzięki nim w XV w. rycerstwo przekształciło się w szlachtę, która współrządziła państwem.\nSejmiki – zjazdy szlachty danego województwa lub ziemi: podejmowały decyzje o sprawach państwa i przekazywały je sejmowi przez posłów.\nSejm walny – instytucja decydująca o najważniejszych sprawach państwa, składająca się z trzech stanów sejmujących: króla, izby senatorskiej – senatorami byli magnaci świeccy i duchowni – oraz izby poselskiej, czyli posłów szlachty wybranych przez sejmiki.\nKonstytucja Nihil novi (1505): sejm nie uchwali „nic nowego” bez zgody wszystkich trzech stanów sejmujących.\nUstrój Polski (XVI–XVIII w.): nie powstała monarchia stanowa; ustrój nazywamy monarchiczno-szlacheckim."],"216":["Polska i Litwa w XV wieku – tolerancja religijna","39. Polska i Litwa w XV wieku\nOś czasu: 1400 – odnowienie uniwersytetu w Krakowie; 1489 – ukończenie ołtarza Wita Stwosza.\nPrzypomnij, na czym polegała różnica między monarchią dziedziczną a elekcyjną.\nTolerancja religijna\nPod koniec XV w. Polska i Litwa liczyły ok. 6 milionów ludzi. Byli oni zamożniejsi od swoich przodków, ale wciąż ubożsi od mieszkańców krajów Europy Zachodniej.\nZachód rozwijał się od czasów Karola Wielkiego. Polska dopiero za rządów Mieszka I, czyli 200 lat później, zaczęła przyswajać chrześcijaństwo oraz osiągnięcia zachodniej cywilizacji: prawa, obyczaje, naukę, technikę, sztukę.\nOd drugiej połowy XIV w. Polacy wnosili własne wartości do kultury europejskiej. Najważniejszą z nich była tolerancja religijna.\nW średniowiecznej Europie Zachodniej tolerancja religijna nie istniała. Wszyscy musieli wyznawać religię katolicką; tolerowano tylko Żydów. Jeśli ktoś głosił poglądy niezgodne z nauką Kościoła, groziły mu surowe kary.\nW Polsce było inaczej. Kazimierz Wielki przyłączył do państwa Ruś Halicką, zamieszkaną przez prawosławnych Rusinów, i nie nakłaniał ich do przejścia na katolicyzm.\nOd zawarcia unii polsko-litewskiej w obu państwach żyli nie tylko Polacy, katolicy, oraz Rusini, prawosławni, ale też Litwini, którzy musieli się nawrócić na katolicyzm, Żydzi, wyznawcy judaizmu, i Tatarzy, muzułmanie. Żeby unia mogła przetrwać, mieszkańcy Polski i Litwy musieli się nauczyć tolerancji dla innych religii, narodowości oraz kultur. Dlatego polscy duchowni nawracali Litwinów „słowem i przykładem”, a nie karami.\n1. Od kogo się wywodziła i kiedy rządziła Polską dynastia Jagiellonów? 2. Dlaczego mieszkańcy Polski i Litwy musieli się nauczyć tolerancji dla innych religii, narodowości i kultur?\nWnętrze XV-wiecznej Starej Synagogi w Krakowie. Wielu Żydów przybywało do Polski z Zachodu, gdzie często byli prześladowani."],"217":["Średniowieczne szkoły i religia panująca","Średniowieczne szkoły\nW średniowieczu nie było takich szkół jak dziś. Przy większości parafii istniały za to szkoły parafialne. Do każdej chodziło zwykle 15–20 chłopców – synów rycerzy, mieszczan, a czasem chłopów. Jednak większość chłopców w ogóle nie chodziła do szkoły, a dziewczynki mogły się uczyć tylko w żeńskich klasztorach.\nKościół prowadził szkoły parafialne głównie po to, by kształcić przyszłych księży. Nauczycielem był ksiądz albo np. organista, który uczył chłopców przede wszystkim czytania i pisania po łacinie, a także zasad katechizmu, trochę matematyki oraz śpiewu kościelnego.\nNa wyższym poziomie stały szkoły katedralne, mieszczące się przy katedrach. Zwykle kształciły przyszłych księży, ale nie tylko. W XV w. sztuka czytania i pisania coraz częściej przydawała się szlachcie, kupcom, a nawet bogatym chłopom – głównie do prowadzenia interesów handlowych.\n3. Kto chodził do szkół parafialnych i katedralnych? 4. Czego uczono w szkołach parafialnych? 5. Kto i do czego potrzebował umiejętności czytania i pisania w XV w.?\nNiemiecka ilustracja z początków XVI w. ukazuje świecką szkołę miejską. Takie szkoły zaczęły powstawać pod koniec średniowiecza. Chodzili do nich głównie synowie kupców. Uczyli się przedmiotów praktycznych, takich jak rachunki i podstawy prawa.\nDawniej a dziś – Religia panująca. Od czasów starożytnych władcy wykorzystywali religię do umacniania swej władzy. Kapłani mówili ludziom, że mają być posłuszni monarsze, który sam jest bogiem albo rządzi z woli Boga. Dlatego władcom zależało na istnieniu religii panującej. W średniowiecznej Europie Zachodniej byli nią katolicyzm – mieli go wyznawać wszyscy lub prawie wszyscy mieszkańcy państwa. Religia panująca przynosiła korzyści nie tylko monarsze, ale też ludziom z nim związanym. Otrzymywali od niego majątki i zaszczytne stanowiska. Z kolei ubożsi poddani wierzyli, że państwo jest tak urządzone, jak chciał Bóg. Dopiero w XVIII w. myśliciele zaczęli oddzielać politykę od religii. Stwierdzili, że ustrój państwa to wynik umowy między ludźmi, a nie woli Boga. Gdy Europejczycy przyjęli te poglądy, coraz bardziej powszechna zaczęła się stawać tolerancja religijna, która istnieje do dziś.\nPytania: co to znaczy, że katolicyzm był religią panującą w średniowiecznej Europie Zachodniej? Kiedy i dlaczego tolerancja religijna stała się bardziej powszechna?"],"218":["Infografika – Ołtarz Wita Stwosza","INFOGRAFIKA. Ołtarz Wita Stwosza.\nW drugiej połowie XV w. przybył do Krakowa niemiecki rzeźbiarz Wit Stwosz. Spędził tam prawie 20 lat; potem wyjechał z niewyjaśnionych przyczyn. W kościele Mariackim w Krakowie wykonał drewniany ołtarz Zaśnięcia Najświętszej Marii Panny, nazywany ołtarzem Wita Stwosza. Artysta pracował nad swoim arcydziełem 12 lat, 1477–1489.\nModelami Wita Stwosza byli krakowscy mieszczanie. Zostali ukazani tak wiernie, że dziś można rozpoznać trapiące ich choroby, m.in. raka skóry.\n1. Skrzydła boczne ukazują radosne sceny z życia Marii i Chrystusa. 2. Zwiastowanie. 3. Boże Narodzenie. 4. Pokłon trzech króli. 5. Część centralna przedstawia zaśnięcie Najświętszej Marii Panny, otoczonej przez dwunastu apostołów. Na ich twarzach malują się uczucia, takie jak smutek, strach i ciekawość. 6. Maria, już wniebowzięta, unosi się z Chrystusem nad Ziemią. 7. Św. Piotr czyta modlitwę za umierających. 8. Maria, ukazana jako młoda kobieta, osuwa się na kolana. Zasypia, tzn. umiera bez bólu. 9. Św. Jakub Starszy podtrzymuje Marię. 10. Św. Jan trzyma płaszcz Marii. 11. Zmartwychwstanie Chrystusa. 12. Wniebowstąpienie Chrystusa. 13. Zesłanie Ducha Świętego.\nCo i w jaki sposób przedstawia ołtarz Wita Stwosza?"],"219":["Ołtarz Wita Stwosza – część druga","Dalsza część infografiki „Ołtarz Wita Stwosza”.\nCzęść centralna przedstawia zaśnięcie Najświętszej Marii Panny w otoczeniu dwunastu apostołów. Maria, ukazana jako młoda kobieta, osuwa się na kolana; zasypia, czyli umiera bez bólu. Św. Jakub Starszy ją podtrzymuje, św. Jan trzyma jej płaszcz, św. Piotr czyta modlitwę za umierających. Powyżej Maria, już wniebowzięta, unosi się z Chrystusem nad Ziemią.\nNa prawym skrzydle widoczne są sceny oznaczone numerami: 11. Zmartwychwstanie Chrystusa, 12. Wniebowstąpienie Chrystusa, 13. Zesłanie Ducha Świętego."],"220":["Uniwersytet w Krakowie i wielcy uczeni XV-wiecznej Polski","Uniwersytet w Krakowie\nW XV w. jedynym polskim uniwersytetem była Akademia Krakowska. Miała wówczas znakomitych profesorów astronomii, matematyki i geografii. W Krakowie studiowali Czesi, Węgrzy, Niemcy, Włosi, Holendrzy – i nie tylko. Co trzeci żak był cudzoziemcem.\nStudentami zwykle zostawali chłopcy co najmniej czternastoletni, dobrze znający język łaciński. Ale zdarzali się też ośmiolatkowie, którzy dopiero w Akademii uczyli się łaciny.\nXV-wieczna Akademia Krakowska kształciła przede wszystkim prawników, lekarzy, matematyków, teologów i astronomów. Zostawali nimi nie tylko synowie ludzi zamożnych. Co drugi absolwent uniwersytetu pochodził ze stanu chłopskiego. Istniały nawet stypendia dla najuboższych, aby i oni mogli studiować.\n6. Kto studiował na uniwersytecie w Krakowie w XV w.? 7. Kim można było zostać po ukończeniu Akademii Krakowskiej?\nWładysław Jagiełło wręcza pierwszemu rektorowi Akademii Krakowskiej dokument z przywilejami dla profesorów i studentów. Zostali oni m.in. zwolnieni z różnych opłat. Tak ukazał tę scenę Marcello Bacciarelli.\nStypendium – pieniądze dla studenta, np. od uczelni.\nŻacy mogli się przenosić z jednego uniwersytetu na drugi, np. z Polski do Włoch. Nie musieli się uczyć włoskiego, bo wszędzie wykłady były po łacinie.\nSala na piętrze Collegium Maius, XV-wiecznego budynku dawnej Akademii Krakowskiej. Profesorowie i żacy spotykali się tu dwa razy dziennie na posiłkach.\nWielcy uczeni XV-wiecznej Polski\nW Akademii Krakowskiej wykładał wybitny prawnik Paweł Włodkowic, który bronił Polski w sporach z Krzyżakami i jako jeden z pierwszych Europejczyków potępił nawracanie pogan siłą."],"221":["Wielcy uczeni XV-wiecznej Polski – podsumowanie","Paweł Włodkowic przyznał poganom prawo do posiadania własnego państwa, co było wówczas całkowitą nowością.\nNa krakowskim uniwersytecie studiował, lecz go nie ukończył Jan Długosz – najznakomitszy kronikarz polskiego średniowiecza. Był historykiem, duchownym i wychowawcą synów Kazimierza Jagiellończyka. Przez 25 lat pisał po łacinie Roczniki, czyli kroniki sławnego Królestwa Polskiego. Dzieło to nie miało równego sobie w ówczesnej Europie. Kronikarz zawarł w nim dzieje Polski od czasów legendarnych aż po rok swej śmierci (1480).\nNajsłynniejszym absolwentem Akademii Krakowskiej był astronom Mikołaj Kopernik. Udowodnił on, że Ziemia i inne planety krążą wokół Słońca, a nie odwrotnie. O Koperniku powiemy więcej w następnej książce.\n8. Co nowego głosił Paweł Włodkowic? 9. Kim był i czego dokonał Jan Długosz?\nWładztwo – dawniej: władza, rządy.\nTekst źródłowy. Paweł Włodkowic, O władzy papieża i cesarza nad niewiernymi, 1415 r. pisał, że nie wolno zabierać niewiernym ich państw i posiadłości tylko dlatego, że są niewiernymi, ponieważ Bóg stworzył świat dla wszystkich. Bezbożne i niedorzeczne jest twierdzenie, jakoby niewierni nie byli dziś ludźmi niezdolnymi do jakiejś władzy, godności, mocy czy władztwa; gdyby nie byli panami tych rzeczy, można byłoby każdego rabować lub nawet zabijać.\nPytania do tekstu: czy, zdaniem Pawła Włodkowica, zabierać człowiekowi „niewiernemu” jego państwo i posiadłości? Dlaczego? Z jakiego powodu Paweł Włodkowic potępił twierdzenie o niezdolności „niewiernych” do władzy, godności itd.?\nPytania i polecenia. A. Wyjaśnij, jakie wartości i osiągnięcia wniosła do kultury europejskiej XV-wieczna Polska. B. Czym średniowieczna edukacja różniła się od dzisiejszej?\nTo, co najważniejsze. Tolerancja religijna – poszanowanie cudzych wierzeń religijnych; istniała w Polsce Kazimierza Wielkiego, a po unii polsko-litewskiej objęła także Litwę i była wyjątkiem w Europie.\nEdukacja dla chłopców: szkoły parafialne i szkoły katedralne; podstawą nauka czytania i pisania po łacinie.\nAkademia Krakowska w XV w.: miała znakomitych profesorów astronomii, matematyki i geografii; wykłady odbywały się po łacinie; kształciła przede wszystkim prawników, lekarzy, matematyków, teologów i astronomów; co trzeci żak był cudzoziemcem; często studiowali synowie chłopów.\nWielcy uczeni XV-wiecznej Polski: Paweł Włodkowic – prawnik, potępił nawracanie pogan siłą; Jan Długosz – historyk, autor Roczników, czyli Kronik sławnego Królestwa Polskiego; Mikołaj Kopernik – astronom, udowodnił, że Ziemia i inne planety krążą wokół Słońca."]};

async function streamToText(stream){
  const reader=stream.getReader();
  const chunks=[];
  while(true){
    const part=await reader.read();
    if(part.done) break;
    chunks.push(Buffer.from(part.value));
  }
  return Buffer.concat(chunks).toString('utf8');
}

export default async function handler(req,res){
  if(req.method!=='GET') return res.status(405).end();
  const mode=String(req.query.mode||'check');
  if(!['check','import'].includes(mode)) return res.status(400).json({error:'mode must be check or import'});
  const out=[];
  for(const [id,[title,text]] of Object.entries(P)){
    const pathname=`books/historia-5/text/${id}.json`;
    let existing=null;
    try{
      const g=await get(pathname,{access:'private'});
      if(g&&g.statusCode===200){
        const raw=await streamToText(g.stream);
        existing=JSON.parse(raw);
      }
    }catch{}
    const data={bookId:'historia-5',sourcePage:Number(id),title,text,paragraphs:text.split(/\n+/).map(s=>s.trim()).filter(Boolean)};
    if(mode==='import'){
      await put(pathname,JSON.stringify(data),{access:'private',addRandomSuffix:false,allowOverwrite:true,contentType:'application/json'});
    }
    out.push({id,existed:!!existing,existingTitle:existing?.title||null,existingChars:typeof existing?.text==='string'?existing.text.length:0,newChars:text.length,paragraphs:data.paragraphs.length});
  }
  res.setHeader('Cache-Control','no-store');
  return res.status(200).json({ok:true,mode,count:out.length,pages:out});
}
